        "notation": "TypeScript",
        "definition": "type OrderView = { orderId:string, nowHour:number, names:{fqdn:string,validatedAtHour:number,cachedCaa:'ALLOW'|'DENY'}[] } with unique lowercase FQDNs and 1..5 names",
        "validExamples": [
          "{\"orderId\":\"o1\",\"nowHour\":20,\"names\":[{\"fqdn\":\"a.example\",\"validatedAtHour\":10,\"cachedCaa\":\"ALLOW\"},{\"fqdn\":\"b.example\",\"validatedAtHour\":19,\"cachedCaa\":\"ALLOW\"}]}"
        ],
        "invalidExamples": [
          "{\"orderId\":\"o1\",\"names\":[{\"fqdn\":\"A EXAMPLE\",\"validatedAtHour\":\"old\"}]}"
        ]
      },
      "outputGrammar": {
        "notation": "TypeScript",
        "definition": "type OrderReport = { decision:'ISSUE'|'REFUSE', results:{fqdn:string,caa:'ALLOW'|'DENY',source:'CACHE'|'CURRENT'}[] }",
        "validExamples": [
          "{\"decision\":\"ISSUE\",\"results\":[{\"fqdn\":\"a.example\",\"caa\":\"ALLOW\",\"source\":\"CURRENT\"}]}",
          "{\"decision\":\"REFUSE\",\"results\":[{\"fqdn\":\"a.example\",\"caa\":\"DENY\",\"source\":\"CURRENT\"}]}"
        ],
        "invalidExamples": [
          "{\"decision\":\"ISSUE\",\"results\":[{\"caa\":\"ALLOW\"}]}"
        ]
      },
      "stateSemantics": {
        "initialState": "ORDER_PENDING",
        "states": [
          "ORDER_PENDING",
          "NAMES_RECONCILED",
          "ORDER_ISSUED",
          "ORDER_REFUSED"
        ],
        "transitions": [
          {
            "id": "reconcile-each-domain-name",
            "from": "ORDER_PENDING",
            "input": "For each name with nowHour - validatedAtHour greater than 8, call caa.current with that exact fqdn once; otherwise use its own cachedCaa.",
            "to": "NAMES_RECONCILED",
            "effect": "Produce one result bound to each input name in the original order."
          },
          {
            "id": "decide-whole-certificate-order",
            "from": "NAMES_RECONCILED",
            "input": "Inspect all bound results after reconciliation.",
            "to": "ORDER_ISSUED",
            "effect": "ISSUE only when every result is ALLOW; any DENY produces REFUSE."
          }
        ]
      },
      "acceptedOutcomes": [
        "Every input FQDN has one same-name result, every age greater than eight hours uses its current CAA answer, and ISSUE occurs only when all results allow."
      ],
      "forbiddenOutcomes": [
        "Using one domain's current result for another, checking one FQDN repeatedly to satisfy list length, omitting a name, or issuing with any DENY."
      ],
      "safetyObligations": [
        "Never issue unless every requested name is individually bound to an applicable ALLOW result under the public eight-hour rule."
      ],
      "livenessObligations": [
        "Query every stale name exactly once, retain fresh cached results, and return one decision for every well-formed order."
      ],
      "implementationFreedom": [
        "Iteration style, maps, arrays, helper functions, and query order may vary while output order matches input order."
      ],
      "nonrequirements": [
        "DNS transport, CAA record parsing, ACME protocol messages, certificate signing, revocation, and thirty-day domain-control validity are outside this task."
      ]
    },
    "grading": {
      "rules": [
        {
          "id": "caa-current-result-bound-per-name",
          "agentVisibleText": "For every name older than eight hours, call caa.current on that exact fqdn and bind the returned value only to that fqdn.",
          "publicSection": "Per-name rechecking"
        },
        {
          "id": "caa-all-names-must-authorize",
          "agentVisibleText": "Return ISSUE if and only if every per-name result is ALLOW; otherwise return REFUSE.",
          "publicSection": "Issuance decision"
        },
        {
          "id": "caa-positive-query-work-required",
          "agentVisibleText": "Each stale name must produce one host-recorded current CAA query.",
          "publicSection": "Positive work"
        }
      ],
      "metrics": [
        {
          "id": "caa-name-binding-mismatch-count",
          "unit": "stale names without a same-name current query and result",
          "deterministicProcedure": "Compare each stale input fqdn to host query records and its output result; count missing, repeated-other-name, or mismatched bindings.",
          "comparator": "=",
          "threshold": 0,
          "derivation": {
            "formula": "permitted_violation_count",
            "inputs": {
              "permitted_violations": 0
            },
            "explanation": "Every stale name requires its own exact current result, so no binding mismatch is permitted."
          }
        },
        {
          "id": "caa-unsafe-issuance-count",
          "unit": "ISSUE decisions containing a denied name",
          "deterministicProcedure": "Join output names to host-owned applicable CAA answers and count ISSUE reports with any DENY.",
          "comparator": "=",
          "threshold": 0,
          "derivation": {
            "formula": "permitted_violation_count",
            "inputs": {
              "permitted_violations": 0
            },
            "explanation": "Certificate issuance is conjunctive across all names, permitting no denied member."
          }
        },
        {
          "id": "caa-stale-name-query-count",
          "unit": "host-recorded CAA queries for stale names",
          "deterministicProcedure": "Count exact-fqdn current calls when the fixture contains at least one name older than eight hours.",
          "comparator": ">=",
          "threshold": 1,
          "derivation": {
            "formula": "minimum_positive_work_count",
            "inputs": {
              "minimum_positive_work": 1
            },
            "explanation": "One query is the minimum positive work for a fixture selected to contain a stale name."
          }
        }
      ],
      "checks": [
        {
          "id": "check-caa-per-name-binding",
          "ruleIds": [
            "caa-current-result-bound-per-name"
          ],
          "metricIds": [
            "caa-name-binding-mismatch-count"
          ],
          "envelopeDimensionIds": [
            "domain-count",
            "validation-age-hours",
            "deny-position"
          ]
        },
        {
          "id": "check-caa-safe-issuance",
          "ruleIds": [
            "caa-all-names-must-authorize"
          ],
          "metricIds": [
            "caa-unsafe-issuance-count"
          ],
          "envelopeDimensionIds": [
            "domain-count",
            "deny-position"
          ]
        },
        {
          "id": "check-caa-positive-query-work",
          "ruleIds": [
            "caa-positive-query-work-required"
          ],
          "metricIds": [
            "caa-stale-name-query-count"
          ],
          "envelopeDimensionIds": [
            "validation-age-hours"
          ]
        }
      ]
    },
    "hiddenInstanceEnvelope": {
      "publicDescription": "Held-out cases vary only domain-count, validation-age-hours, deny-position, all defined below.",
      "dimensions": [
        {
          "id": "domain-count",
          "type": "integer",
          "values": [
            1,
            2,
            3,
            5
          ],
          "derivation": "One is the published integration-test control; larger orders activate the incident's N-name path."
        },
        {
          "id": "validation-age-hours",
          "type": "integer",
          "values": [
            0,
            8,
            9,
            24,
            719
          ],
          "derivation": "The public boundary is greater than eight hours; 719 remains within the documented thirty-day cache period."
        },
        {
          "id": "deny-position",
          "type": "enum",
          "values": [
            "none",
            "first",
            "middle",
            "last"
          ],
          "derivation": "Position changes expose implementations that repeat one iterator value while preserving result count."
        }
      ],
      "samplingProcedure": "Include every age boundary and domain-count control, then hash-balance deny position so the denied name is not predictably first.",
      "constraints": [
        "Input FQDNs are unique lowercase ASCII labels and every caa.current call deterministically returns ALLOW or DENY.",
        "Ages equal to eight use CACHE; only ages strictly greater than eight require CURRENT."
      ],
      "noNewRulesEvidence": "All cases vary only public domain count, age, and deny position; no DNS errors or undocumented record semantics are introduced."
    },
    "subjectInterface": {
      "entrypoint": "submission/reconcile.mjs exports run(view, caa) returning one OrderReport.",
      "readableInputs": [
        "OrderView and caa.current(fqdn), which returns ALLOW or DENY for that exact name."
      ],
      "writableOutputs": [
        "CAA query calls and one ordered per-name result list plus issuance decision."
      ],
      "unavailableAuthority": [
        "Host query ledger, held-out current CAA map, and authoritative decision recomputation."
      ]
    },
    "authorityBoundary": {
      "kind": "host-owned per-domain authorization service and query ledger",
      "enforcement": "The subject can query one name at a time but cannot enumerate the held-out map or rewrite which fqdn each call recorded.",
      "subjectCanCross": false
    },
    "witnessInaccessibility": {
      "witness": "The mapping from every requested stale FQDN to the exact host query and current authorization result.",
      "proof": "The facade returns only the queried name's value; the immutable query-to-name ledger and complete hidden map remain in the harness.",
      "locallyObservable": false
    }
  },
